-- submissions/reviews
-- The decisions already made on a submission, with the reviewer's name, oldest first.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/submissions.ts. Do not edit by hand.

select r.id, r.reviewer_id as "reviewerId", u.name as "reviewerName", r.decision, r.reason_code as "reasonCode", r.note,
       r.created_at as "createdAt"
from reviews r join users u on u.id = r.reviewer_id
where r.submission_id = $1
order by r.created_at, r.id;
